import{_ as s,o as n,c as e,a}from"./app.DkoUFz-u.js";const g=JSON.parse('{"title":"OAuth 2.0 OIDC 协议","description":"","frontmatter":{},"headers":[],"relativePath":"backend/auth/oauth/oidc.md","filePath":"backend/auth/oauth/oidc.md"}'),o={name:"backend/auth/oauth/oidc.md"};function l(i,t,r,d,h,c){return n(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="oauth-2-0-oidc-协议" tabindex="-1">OAuth 2.0 OIDC 协议 <a class="header-anchor" href="#oauth-2-0-oidc-协议" aria-label="Permalink to &quot;OAuth 2.0 OIDC 协议&quot;">​</a></h1><blockquote><p><strong>请注意</strong>：以下信息综合了多个网络技术博客和文档。这些资料在时效性和权威性上可能存在局限，建议你在关键应用场景中，务必参考官方标准协议（如RFC 6749、RFC 7519等）或权威技术文档进行核实。</p></blockquote><h2 id="🎯-一、理解核心概念" tabindex="-1">🎯 一、理解核心概念 <a class="header-anchor" href="#🎯-一、理解核心概念" aria-label="Permalink to &quot;🎯 一、理解核心概念&quot;">​</a></h2><p>首先，我们明确三个核心概念的基本定位：</p><table tabindex="0"><thead><tr><th style="text-align:left;">概念</th><th style="text-align:left;">核心问题</th><th style="text-align:left;">简单比喻</th><th style="text-align:left;">主要贡献</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>认证 (Authentication)</strong></td><td style="text-align:left;"><strong>&quot;你是谁？&quot;</strong></td><td style="text-align:left;">出示你的<strong>身份证</strong>，证明你是你。</td><td style="text-align:left;">验证用户身份。</td></tr><tr><td style="text-align:left;"><strong>授权 (Authorization)</strong></td><td style="text-align:left;"><strong>&quot;你能做什么？&quot;</strong></td><td style="text-align:left;">获得进入某个<strong>房间的钥匙</strong>，但不代表你是房主。</td><td style="text-align:left;">授予资源访问权限。</td></tr><tr><td style="text-align:left;"><strong>OAuth 2.0</strong></td><td style="text-align:left;">**&quot;授权&quot;**的标准协议</td><td style="text-align:left;">把门禁卡（Access Token）委托给保洁员，允许她进入大楼打扫，但无需知道你的房间密码。</td><td style="text-align:left;">提供了一套标准的授权框架和流程。</td></tr><tr><td style="text-align:left;"><strong>OpenID Connect (OIDC)</strong></td><td style="text-align:left;">**&quot;认证&quot;**协议（基于OAuth 2.0）</td><td style="text-align:left;">在委托门禁卡的同时，还拿到了一张包含你姓名、照片的工作证（ID Token），证明了你的身份。</td><td style="text-align:left;">在OAuth 2.0授权的基础上，提供了身份认证层。</td></tr></tbody></table><p>简单来说，<strong>OIDC = OAuth 2.0 + 认证</strong>。OAuth 2.0主要解决授权访问资源的问题，但它本身并不关心用户是谁。OIDC在OAuth 2.0的流程中加入了ID Token，从而解决了身份认证的问题。</p><h2 id="🔑-二、oauth-2-0-详解" tabindex="-1">🔑 二、OAuth 2.0 详解 <a class="header-anchor" href="#🔑-二、oauth-2-0-详解" aria-label="Permalink to &quot;🔑 二、OAuth 2.0 详解&quot;">​</a></h2><p>OAuth 2.0是一个<strong>授权框架</strong>，它允许第三方应用在获得用户同意后，有限度地访问用户存储在资源服务器上的资源，而无需分享用户的密码。</p><h4 id="核心角色" tabindex="-1">核心角色 <a class="header-anchor" href="#核心角色" aria-label="Permalink to &quot;核心角色&quot;">​</a></h4><p>在一个典型的OAuth 2.0流程中，通常包含四个角色：</p><ul><li><strong>资源所有者 (Resource Owner)</strong>：用户本人。</li><li><strong>客户端 (Client)</strong>：试图访问用户资源的第三方应用。</li><li><strong>授权服务器 (Authorization Server)</strong>：验证用户身份并颁发令牌（Token）的服务器。</li><li><strong>资源服务器 (Resource Server)</strong>：存放用户受保护资源的服务器（如API服务器）。</li></ul><h4 id="四种授权模式" tabindex="-1">四种授权模式 <a class="header-anchor" href="#四种授权模式" aria-label="Permalink to &quot;四种授权模式&quot;">​</a></h4><p>OAuth 2.0定义了四种不同的授权模式，以适应不同的应用场景：</p><ol><li><p><strong>授权码模式 (Authorization Code Grant)</strong></p><ul><li><strong>描述</strong>：这是<strong>最完整、最安全</strong>的模式，适用于有后端的Web应用。它通过一个&quot;授权码&quot;作为中间凭证来换取访问令牌，避免了令牌直接暴露在浏览器中。</li><li><strong>流程</strong>：其授权流程主要步骤可概括为：客户端换取授权码，客户端使用授权码换token，客户端使用token访问资源。具体交互流程可参考下图：</li></ul><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">flowchart TD</span></span>
<span class="line"><span class="__shiki_140thh">    A[用户访问客户端] --&gt; B[重定向至授权服务器]</span></span>
<span class="line"><span class="__shiki_140thh">    B --&gt; C{用户登录并授权}</span></span>
<span class="line"><span class="__shiki_140thh">    C --&gt;|同意| D[授权服务器返回&lt;br&gt;授权码至回调地址]</span></span>
<span class="line"><span class="__shiki_140thh">    D --&gt; E[客户端使用授权码&lt;br&gt;向授权服务器请求令牌]</span></span>
<span class="line"><span class="__shiki_140thh">    E --&gt; F[授权服务器校验并返回&lt;br&gt;访问令牌/刷新令牌]</span></span>
<span class="line"><span class="__shiki_140thh">    F --&gt; G[客户端使用访问令牌&lt;br&gt;访问资源服务器]</span></span>
<span class="line"><span class="__shiki_140thh">    G --&gt; H[资源服务器返回受保护资源]</span></span></code></pre></div></li><li><p><strong>隐式授权模式 (Implicit Grant)</strong></p><ul><li><strong>描述</strong>：简化了流程，授权服务器直接返回访问令牌（而不通过授权码）。适用于完全运行在浏览器中的单页应用（SPA），但令牌有在浏览器中暴露的风险，<strong>安全性较低</strong>。现代实践推荐对此类应用使用支持PKCE的授权码模式。</li></ul></li><li><p><strong>密码模式 (Resource Owner Password Credentials Grant)</strong></p><ul><li><strong>描述</strong>：用户将用户名和密码直接交给客户端，客户端用它来换取令牌。这要求客户端是<strong>高度受信任的</strong>（如同一公司内部的应用），因为它需要直接处理用户的密码，<strong>风险较高</strong>，不推荐在第三方应用中使用。</li></ul></li><li><p><strong>客户端模式 (Client Credentials Grant)</strong></p><ul><li><strong>描述</strong>：客户端代表自己而非用户进行认证，直接使用自己的客户端凭证换取令牌。适用于<strong>机器对机器的后端交互</strong>，例如微服务之间的调用。</li></ul></li></ol><h2 id="🔐-三、openid-connect-oidc-详解" tabindex="-1">🔐 三、OpenID Connect (OIDC) 详解 <a class="header-anchor" href="#🔐-三、openid-connect-oidc-详解" aria-label="Permalink to &quot;🔐 三、OpenID Connect (OIDC) 详解&quot;">​</a></h2><p>OIDC在OAuth 2.0的基础上，主要增加了以下内容：</p><h4 id="核心组件-id-token" tabindex="-1">核心组件：ID Token <a class="header-anchor" href="#核心组件-id-token" aria-label="Permalink to &quot;核心组件：ID Token&quot;">​</a></h4><p>ID Token是OIDC的核心，它是一个<strong>JSON Web Token (JWT)</strong>，包含了关于用户身份认证的声明（Claims）。客户端可以解析并验证这个ID Token来确认用户的身份。</p><ul><li><strong>内容</strong>：ID Token的Payload部分包含了一些标准字段，例如： <ul><li><code>iss</code> (Issuer)：签发者。</li><li><code>sub</code> (Subject)：用户唯一标识。</li><li><code>aud</code> (Audience)：受众，即令牌的目标接收方。</li><li><code>exp</code> (Expiration)：过期时间。</li><li><code>iat</code> (Issued At)：签发时间。</li><li>还可能包含<code>name</code>, <code>email</code>, <code>picture</code>等用户信息。</li></ul></li></ul><h4 id="oidc-流程" tabindex="-1">OIDC 流程 <a class="header-anchor" href="#oidc-流程" aria-label="Permalink to &quot;OIDC 流程&quot;">​</a></h4><p>OIDC最常用的流程是<strong>授权码流程</strong>，它在标准的OAuth 2.0授权码流程上做了微小但重要的扩展：</p><ol><li><strong>认证请求</strong>：客户端在发起授权请求时，必须在<code>scope</code>参数中包含<code>openid</code>，并将<code>response_type</code>设置为<code>code</code>。</li><li><strong>用户认证与授权</strong>：与OAuth 2.0相同，用户在授权服务器上登录并同意授权。</li><li><strong>获取授权码</strong>：授权服务器重定向回客户端并返回授权码。</li><li><strong>换取Token</strong>：客户端使用授权码向授权服务器的令牌端点（<code>token_endpoint</code>）发送请求。<strong>关键的不同点在于</strong>，授权服务器的响应中不仅包含访问令牌（Access Token），还会包含一个<strong>ID Token</strong>。<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">// Token端点响应示例</span></span>
<span class="line"><span class="__shiki_140thh">{</span></span>
<span class="line"><span class="__shiki_dzsirb">    &quot;access_token&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;eyJhbGciOi...&quot;</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_dzsirb">    &quot;id_token&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;eyJhbGciOi...&quot;</span><span class="__shiki_140thh">, </span><span class="__shiki_21nrsd">// 新增的ID Token</span></span>
<span class="line"><span class="__shiki_dzsirb">    &quot;token_type&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;Bearer&quot;</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_dzsirb">    &quot;expires_in&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_dzsirb">3600</span></span>
<span class="line"><span class="__shiki_140thh">}</span></span></code></pre></div></li><li><strong>可选：获取用户信息</strong>：客户端可以使用Access Token访问<strong>用户信息端点（<code>userinfo_endpoint</code>）</strong> 来获取更详细的用户资料。</li></ol><h4 id="关键端点-endpoint" tabindex="-1">关键端点 (Endpoint) <a class="header-anchor" href="#关键端点-endpoint" aria-label="Permalink to &quot;关键端点 (Endpoint)&quot;">​</a></h4><p>一个完整的OIDC提供者（OP）通常会暴露以下端点，这些信息可以在其发现文档（<code>/.well-known/openid-configuration</code>）中找到：</p><ul><li><code>authorization_endpoint</code>：处理认证和授权请求。</li><li><code>token_endpoint</code>：用于兑换令牌。</li><li><code>userinfo_endpoint</code>：用于获取用户信息。</li><li><code>jwks_uri</code>：提供用于验证ID Token签名的公钥。</li></ul><h2 id="💎-四、总结与学习建议" tabindex="-1">💎 四、总结与学习建议 <a class="header-anchor" href="#💎-四、总结与学习建议" aria-label="Permalink to &quot;💎 四、总结与学习建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">OAuth 2.0</th><th style="text-align:left;">OpenID Connect</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>主要目的</strong></td><td style="text-align:left;"><strong>授权</strong> (Delegate Access)</td><td style="text-align:left;"><strong>认证</strong> (Authentication)</td></tr><tr><td style="text-align:left;"><strong>核心输出</strong></td><td style="text-align:left;">Access Token</td><td style="text-align:left;">ID Token (JWT) + Access Token</td></tr><tr><td style="text-align:left;"><strong>令牌用途</strong></td><td style="text-align:left;">访问受保护的资源</td><td style="text-align:left;">证明用户身份 + 访问受保护的资源</td></tr><tr><td style="text-align:left;"><strong>协议关系</strong></td><td style="text-align:left;">基础授权框架</td><td style="text-align:left;">构建于OAuth 2.0之上的认证协议</td></tr></tbody></table><p>为了更扎实地掌握这些知识，我建议你：</p><ol><li><strong>动手实践</strong>：找一个支持OIDC的平台（如Google、Authing等），注册一个应用，亲自走一遍授权码流程。</li><li><strong>查看真实数据</strong>：使用像 <a href="https://jwt.io" target="_blank" rel="noreferrer">jwt.io</a> 这样的工具，解码一个ID Token，观察其内部结构。</li><li><strong>阅读官方资料</strong>：深入学习时，务必查阅 <a href="https://tools.ietf.org/html/rfc6749" target="_blank" rel="noreferrer">OAuth 2.0 RFC 6749</a> 和 <a href="https://openid.net/specs/openid-connect-core-1_0.html" target="_blank" rel="noreferrer">OpenID Connect Core 1.0</a> 标准文档。</li></ol>`,29)])])}const u=s(o,[["render",l]]);export{g as __pageData,u as default};
